# Let's structure the output with colors in specific zones
# Maybe colors in left (input cols 0-4) go to edges of output, colors in center (input cols 2-3) go to centers, colors in right go to edges

def zone_transform(grid):
    """Colors in different zones get different output positions"""
    h = len(grid)
    w = len(grid[0])

    # Collect colors by zone
    left_colors = {}  # (r, c_in_left)
    center_colors = {}  # (r, c_in_center)
    right_colors = {}  # (r, c_in_right)

    for r in range(h):
        left_part = grid[r][:w//2]
        center_part = grid[r][w//2:w//2+2]
        right_part = grid[r][w//2+2:w]

        for c in range(w//2):
            if left_part[c] in [2,3,4,7]:
                if (r, c) not in left_colors:
                    left_colors[(r,c)] = left_part[c]

        for c in range(2):
            if center_part[c] in [2,3,4,7]:
                key = (r, c + w//2)
                if key not in center_colors:
                    center_colors[key] = center_part[c]

        for c in range(w//2+2, w):
            if right_part[c-w//2-2] in [2,3,4,7]:
                if (r, c) not in right_colors:
                    right_colors[(r,c)] = right_part[c]

    print("Left colors:")
    for k, v in sorted(left_colors.items()):
        print(f"  {k}: {v}")
    print("Center colors:")
    for k, v in sorted(center_colors.items()):
        print(f"  {k}: {v}")
    print("Right colors:")
    for k, v in sorted(right_colors.items()):
        print(f"  {k}: {v}")

    return {}

